// Extended branch-coverage tests for useBroadcasts hooks.
//
// The existing tests/useBroadcasts.test.tsx covers the main behavioral paths.
// This file fills the remaining branch gaps:
//   - non-Error fallback messages in useBroadcastsList / useBroadcast /
//     useBroadcastRecipients / useBroadcastMutations
//   - useBroadcast (single): loading → ready, error, non-Error fallback, refresh
//   - useBroadcastRecipients: loading → ready, error, non-Error fallback
//   - useBroadcastRecipientsLive: SCHEDULED state also subscribes (LIVE_STATES set)
//   - useBroadcastMutations: update / non-Error fallbacks for each mutation

import { describe, it, expect, vi, beforeEach } from "vitest";
import { renderHook, act, waitFor } from "@testing-library/react";
import type {
  Broadcast,
  ListBroadcastsResponse,
  ListBroadcastRecipientsResponse,
} from "../../src/api/types";
import type { BroadcastRecipientEvent } from "../../src/api/ws";

const BROADCAST: Broadcast = {
  id: "b1",
  org_id: "o1",
  name: "Summer promo",
  body: "Hi {{name}}",
  target_kind: "CONTACT_GROUP",
  target_id: "g1",
  channel_id: null,
  state: "DRAFT",
  scheduled_at: null,
  sent_at: null,
  recipient_count: 10,
  sent_count: 0,
  failed_count: 0,
  skipped_count: 0,
  queued_count: 10,
  created_by: "user-1",
  created_at: "2026-06-01T00:00:00Z",
  updated_at: "2026-06-01T00:00:00Z",
};

const LIST_RESP: ListBroadcastsResponse = {
  broadcasts: [BROADCAST],
  next_page_token: "",
};

const RECIPIENTS_RESP: ListBroadcastRecipientsResponse = {
  recipients: [
    {
      id: "r1",
      broadcast_id: "b1",
      contact_id: "c1",
      contact_display_name: "Alice",
      contact_identifier: "alice@example.com",
      state: "QUEUED",
      error_reason: null,
      sent_at: null,
    },
  ],
  next_page_token: "",
};

// ─── Mock api/broadcasts ──────────────────────────────────────────────────────

vi.mock("../../src/api/broadcasts", () => ({
  listBroadcasts: vi.fn(),
  getBroadcast: vi.fn(),
  createBroadcast: vi.fn(),
  updateBroadcast: vi.fn(),
  scheduleBroadcast: vi.fn(),
  sendNowBroadcast: vi.fn(),
  cancelBroadcast: vi.fn(),
  deleteBroadcast: vi.fn(),
  listBroadcastRecipients: vi.fn(),
}));

import * as broadcastsApi from "../../src/api/broadcasts";

// ─── Mock api/ws — controllable subscribeBroadcastRecipient ──────────────────

const wsListeners = new Set<(ev: BroadcastRecipientEvent) => void>();
const unsubscribeSpy = vi.fn();

vi.mock("../../src/api/ws", () => ({
  subscribeBroadcastRecipient: vi.fn(
    (listener: (ev: BroadcastRecipientEvent) => void): (() => void) => {
      wsListeners.add(listener);
      return () => {
        wsListeners.delete(listener);
        unsubscribeSpy();
      };
    },
  ),
}));

import * as wsApi from "../../src/api/ws";

// ─── useBroadcastsList — non-Error fallback ───────────────────────────────────

describe("useBroadcastsList (branch: non-Error fallback)", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("uses fallback message when non-Error is thrown", async () => {
    vi.mocked(broadcastsApi.listBroadcasts).mockRejectedValue("plain string");

    const { useBroadcastsList } = await import("../../src/hooks/useBroadcasts");
    const { result } = renderHook(() => useBroadcastsList());

    await waitFor(() => {
      expect(result.current.state.tag).toBe("error");
    });

    if (result.current.state.tag === "error") {
      expect(result.current.state.message).toBe("Failed to load broadcasts");
    }
  });
});

// ─── useBroadcast (single) ────────────────────────────────────────────────────

describe("useBroadcast", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("starts in loading state and transitions to ready on success", async () => {
    vi.mocked(broadcastsApi.getBroadcast).mockResolvedValue(BROADCAST);

    const { useBroadcast } = await import("../../src/hooks/useBroadcasts");
    const { result } = renderHook(() => useBroadcast("b1"));

    expect(result.current.state.tag).toBe("loading");

    await waitFor(() => {
      expect(result.current.state.tag).toBe("ready");
    });

    if (result.current.state.tag === "ready") {
      expect(result.current.state.broadcast.id).toBe("b1");
    }
  });

  it("transitions to error when getBroadcast rejects with Error", async () => {
    vi.mocked(broadcastsApi.getBroadcast).mockRejectedValue(new Error("not found"));

    const { useBroadcast } = await import("../../src/hooks/useBroadcasts");
    const { result } = renderHook(() => useBroadcast("b1"));

    await waitFor(() => {
      expect(result.current.state.tag).toBe("error");
    });

    if (result.current.state.tag === "error") {
      expect(result.current.state.message).toBe("not found");
    }
  });

  it("uses fallback message when non-Error is thrown", async () => {
    vi.mocked(broadcastsApi.getBroadcast).mockRejectedValue(undefined);

    const { useBroadcast } = await import("../../src/hooks/useBroadcasts");
    const { result } = renderHook(() => useBroadcast("b1"));

    await waitFor(() => {
      expect(result.current.state.tag).toBe("error");
    });

    if (result.current.state.tag === "error") {
      expect(result.current.state.message).toBe("Failed to load broadcast");
    }
  });

  it("refresh re-fetches the broadcast", async () => {
    vi.mocked(broadcastsApi.getBroadcast).mockResolvedValue(BROADCAST);

    const { useBroadcast } = await import("../../src/hooks/useBroadcasts");
    const { result } = renderHook(() => useBroadcast("b1"));

    await waitFor(() => expect(result.current.state.tag).toBe("ready"));

    act(() => {
      result.current.refresh();
    });

    await waitFor(() => {
      expect(broadcastsApi.getBroadcast).toHaveBeenCalledTimes(2);
    });
  });
});

// ─── useBroadcastRecipients ────────────────────────────────────────────────────

describe("useBroadcastRecipients", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("starts in loading state and transitions to ready on success", async () => {
    vi.mocked(broadcastsApi.listBroadcastRecipients).mockResolvedValue(
      RECIPIENTS_RESP,
    );

    const { useBroadcastRecipients } = await import(
      "../../src/hooks/useBroadcasts"
    );
    const { result } = renderHook(() => useBroadcastRecipients("b1"));

    expect(result.current.state.tag).toBe("loading");

    await waitFor(() => {
      expect(result.current.state.tag).toBe("ready");
    });

    if (result.current.state.tag === "ready") {
      expect(result.current.state.response.recipients).toHaveLength(1);
    }
  });

  it("transitions to error when listBroadcastRecipients rejects with Error", async () => {
    vi.mocked(broadcastsApi.listBroadcastRecipients).mockRejectedValue(
      new Error("forbidden"),
    );

    const { useBroadcastRecipients } = await import(
      "../../src/hooks/useBroadcasts"
    );
    const { result } = renderHook(() => useBroadcastRecipients("b1"));

    await waitFor(() => {
      expect(result.current.state.tag).toBe("error");
    });

    if (result.current.state.tag === "error") {
      expect(result.current.state.message).toBe("forbidden");
    }
  });

  it("uses fallback message when non-Error is thrown", async () => {
    vi.mocked(broadcastsApi.listBroadcastRecipients).mockRejectedValue("oops");

    const { useBroadcastRecipients } = await import(
      "../../src/hooks/useBroadcasts"
    );
    const { result } = renderHook(() => useBroadcastRecipients("b1"));

    await waitFor(() => {
      expect(result.current.state.tag).toBe("error");
    });

    if (result.current.state.tag === "error") {
      expect(result.current.state.message).toBe("Failed to load recipients");
    }
  });

  it("passes params to listBroadcastRecipients", async () => {
    vi.mocked(broadcastsApi.listBroadcastRecipients).mockResolvedValue({
      recipients: [],
      next_page_token: "",
    });

    const { useBroadcastRecipients } = await import(
      "../../src/hooks/useBroadcasts"
    );
    renderHook(() => useBroadcastRecipients("b1", { state: "SENT", page_size: 20 }));

    await waitFor(() => {
      expect(broadcastsApi.listBroadcastRecipients).toHaveBeenCalledWith(
        "b1",
        expect.objectContaining({ state: "SENT", page_size: 20 }),
      );
    });
  });

  it("refresh re-fetches recipients", async () => {
    vi.mocked(broadcastsApi.listBroadcastRecipients).mockResolvedValue(
      RECIPIENTS_RESP,
    );

    const { useBroadcastRecipients } = await import(
      "../../src/hooks/useBroadcasts"
    );
    const { result } = renderHook(() => useBroadcastRecipients("b1"));

    await waitFor(() => expect(result.current.state.tag).toBe("ready"));

    act(() => {
      result.current.refresh();
    });

    await waitFor(() => {
      expect(broadcastsApi.listBroadcastRecipients).toHaveBeenCalledTimes(2);
    });
  });
});

// ─── useBroadcastRecipientsLive — SCHEDULED state also subscribes ─────────────

describe("useBroadcastRecipientsLive (branch: SCHEDULED live state)", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    wsListeners.clear();
    unsubscribeSpy.mockClear();
  });

  it("opens a subscription when broadcast is SCHEDULED (part of LIVE_STATES)", async () => {
    vi.mocked(broadcastsApi.listBroadcastRecipients).mockResolvedValue(
      RECIPIENTS_RESP,
    );

    const { useBroadcastRecipientsLive } = await import(
      "../../src/hooks/useBroadcasts"
    );
    renderHook(() => useBroadcastRecipientsLive("b1", "SCHEDULED"));

    await waitFor(() =>
      expect(broadcastsApi.listBroadcastRecipients).toHaveBeenCalledTimes(1),
    );

    expect(wsApi.subscribeBroadcastRecipient).toHaveBeenCalledOnce();
  });
});

// ─── useBroadcastMutations — update + non-Error fallbacks ────────────────────

describe("useBroadcastMutations (branch coverage)", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("update calls updateBroadcast and invokes onSuccess", async () => {
    const updated = { ...BROADCAST, name: "Updated" };
    vi.mocked(broadcastsApi.updateBroadcast).mockResolvedValue(updated);
    const onSuccess = vi.fn();

    const { useBroadcastMutations } = await import("../../src/hooks/useBroadcasts");
    const { result } = renderHook(() => useBroadcastMutations());

    await act(async () => {
      await result.current.update("b1", { name: "Updated" }, onSuccess);
    });

    expect(broadcastsApi.updateBroadcast).toHaveBeenCalledWith("b1", {
      name: "Updated",
    });
    expect(onSuccess).toHaveBeenCalledWith(updated);
    expect(result.current.pending).toBe(false);
    expect(result.current.error).toBeNull();
  });

  it("update sets error on Error rejection", async () => {
    vi.mocked(broadcastsApi.updateBroadcast).mockRejectedValue(
      new Error("conflict"),
    );

    const { useBroadcastMutations } = await import("../../src/hooks/useBroadcasts");
    const { result } = renderHook(() => useBroadcastMutations());

    await act(async () => {
      await result.current.update("b1", { name: "X" });
    });

    expect(result.current.error).toBe("conflict");
  });

  it("create uses fallback error message when non-Error is thrown", async () => {
    vi.mocked(broadcastsApi.createBroadcast).mockRejectedValue("unexpected");

    const { useBroadcastMutations } = await import("../../src/hooks/useBroadcasts");
    const { result } = renderHook(() => useBroadcastMutations());

    await act(async () => {
      await result.current.create({
        name: "x",
        body: "y",
        target_kind: "CONTACT",
        target_id: "c1",
      });
    });

    expect(result.current.error).toBe("Create failed");
  });

  it("update uses fallback error message when non-Error is thrown", async () => {
    vi.mocked(broadcastsApi.updateBroadcast).mockRejectedValue(null);

    const { useBroadcastMutations } = await import("../../src/hooks/useBroadcasts");
    const { result } = renderHook(() => useBroadcastMutations());

    await act(async () => {
      await result.current.update("b1", {});
    });

    expect(result.current.error).toBe("Update failed");
  });

  it("schedule uses fallback error message when non-Error is thrown", async () => {
    vi.mocked(broadcastsApi.scheduleBroadcast).mockRejectedValue(42);

    const { useBroadcastMutations } = await import("../../src/hooks/useBroadcasts");
    const { result } = renderHook(() => useBroadcastMutations());

    await act(async () => {
      await result.current.schedule("b1", { send_at: "2026-06-01T12:00:00Z" });
    });

    expect(result.current.error).toBe("Schedule failed");
  });

  it("sendNow uses fallback error message when non-Error is thrown", async () => {
    vi.mocked(broadcastsApi.sendNowBroadcast).mockRejectedValue(undefined);

    const { useBroadcastMutations } = await import("../../src/hooks/useBroadcasts");
    const { result } = renderHook(() => useBroadcastMutations());

    await act(async () => {
      await result.current.sendNow("b1");
    });

    expect(result.current.error).toBe("Send failed");
  });

  it("cancel uses fallback error message when non-Error is thrown", async () => {
    vi.mocked(broadcastsApi.cancelBroadcast).mockRejectedValue("nope");

    const { useBroadcastMutations } = await import("../../src/hooks/useBroadcasts");
    const { result } = renderHook(() => useBroadcastMutations());

    await act(async () => {
      await result.current.cancel("b1");
    });

    expect(result.current.error).toBe("Cancel failed");
  });

  it("remove uses fallback error message when non-Error is thrown", async () => {
    vi.mocked(broadcastsApi.deleteBroadcast).mockRejectedValue(false);

    const { useBroadcastMutations } = await import("../../src/hooks/useBroadcasts");
    const { result } = renderHook(() => useBroadcastMutations());

    await act(async () => {
      await result.current.remove("b1");
    });

    expect(result.current.error).toBe("Delete failed");
  });
});

// ─── useBroadcastsList — params state filter branch ──────────────────────────

describe("useBroadcastsList (branch: params)", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("re-fetches when params change", async () => {
    vi.mocked(broadcastsApi.listBroadcasts).mockResolvedValue(LIST_RESP);

    const { useBroadcastsList } = await import("../../src/hooks/useBroadcasts");
    let params: { state?: string } = {};
    const { result, rerender } = renderHook(() => useBroadcastsList(params));

    await waitFor(() => expect(result.current.state.tag).toBe("ready"));

    params = { state: "SCHEDULED" };
    rerender();

    await waitFor(() => {
      expect(broadcastsApi.listBroadcasts).toHaveBeenCalledTimes(2);
    });
  });
});

// ─── useBroadcastMutations — onSuccess callbacks for schedule / sendNow / cancel / remove ─

describe("useBroadcastMutations (onSuccess callbacks)", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("create calls onSuccess with the returned broadcast", async () => {
    vi.mocked(broadcastsApi.createBroadcast).mockResolvedValue(BROADCAST);
    const onSuccess = vi.fn();

    const { useBroadcastMutations } = await import("../../src/hooks/useBroadcasts");
    const { result } = renderHook(() => useBroadcastMutations());

    await act(async () => {
      await result.current.create(
        { name: "x", body: "y", target_kind: "CONTACT", target_id: "c1" },
        onSuccess,
      );
    });

    expect(onSuccess).toHaveBeenCalledWith(BROADCAST);
    expect(result.current.pending).toBe(false);
    expect(result.current.error).toBeNull();
  });

  it("schedule calls onSuccess with the returned broadcast", async () => {
    const scheduled = { ...BROADCAST, state: "SCHEDULED" as const };
    vi.mocked(broadcastsApi.scheduleBroadcast).mockResolvedValue(scheduled);
    const onSuccess = vi.fn();

    const { useBroadcastMutations } = await import("../../src/hooks/useBroadcasts");
    const { result } = renderHook(() => useBroadcastMutations());

    await act(async () => {
      await result.current.schedule("b1", { send_at: "2026-06-01T12:00:00Z" }, onSuccess);
    });

    expect(onSuccess).toHaveBeenCalledWith(scheduled);
    expect(result.current.pending).toBe(false);
    expect(result.current.error).toBeNull();
  });

  it("schedule sets Error message on Error rejection", async () => {
    vi.mocked(broadcastsApi.scheduleBroadcast).mockRejectedValue(
      new Error("deadline exceeded"),
    );

    const { useBroadcastMutations } = await import("../../src/hooks/useBroadcasts");
    const { result } = renderHook(() => useBroadcastMutations());

    await act(async () => {
      await result.current.schedule("b1", { send_at: "2026-06-01T12:00:00Z" });
    });

    expect(result.current.error).toBe("deadline exceeded");
  });

  it("sendNow calls onSuccess with the returned broadcast", async () => {
    const sending = { ...BROADCAST, state: "SENDING" as const };
    vi.mocked(broadcastsApi.sendNowBroadcast).mockResolvedValue(sending);
    const onSuccess = vi.fn();

    const { useBroadcastMutations } = await import("../../src/hooks/useBroadcasts");
    const { result } = renderHook(() => useBroadcastMutations());

    await act(async () => {
      await result.current.sendNow("b1", onSuccess);
    });

    expect(onSuccess).toHaveBeenCalledWith(sending);
  });

  it("sendNow sets Error message on Error rejection", async () => {
    vi.mocked(broadcastsApi.sendNowBroadcast).mockRejectedValue(
      new Error("not found"),
    );

    const { useBroadcastMutations } = await import("../../src/hooks/useBroadcasts");
    const { result } = renderHook(() => useBroadcastMutations());

    await act(async () => {
      await result.current.sendNow("b1");
    });

    expect(result.current.error).toBe("not found");
  });

  it("cancel calls onSuccess with the returned broadcast", async () => {
    const cancelled = { ...BROADCAST, state: "CANCELED" as const };
    vi.mocked(broadcastsApi.cancelBroadcast).mockResolvedValue(cancelled);
    const onSuccess = vi.fn();

    const { useBroadcastMutations } = await import("../../src/hooks/useBroadcasts");
    const { result } = renderHook(() => useBroadcastMutations());

    await act(async () => {
      await result.current.cancel("b1", onSuccess);
    });

    expect(onSuccess).toHaveBeenCalledWith(cancelled);
  });

  it("cancel sets Error message on Error rejection", async () => {
    vi.mocked(broadcastsApi.cancelBroadcast).mockRejectedValue(
      new Error("cannot cancel"),
    );

    const { useBroadcastMutations } = await import("../../src/hooks/useBroadcasts");
    const { result } = renderHook(() => useBroadcastMutations());

    await act(async () => {
      await result.current.cancel("b1");
    });

    expect(result.current.error).toBe("cannot cancel");
  });

  it("remove calls onSuccess after successful delete", async () => {
    vi.mocked(broadcastsApi.deleteBroadcast).mockResolvedValue(null);
    const onSuccess = vi.fn();

    const { useBroadcastMutations } = await import("../../src/hooks/useBroadcasts");
    const { result } = renderHook(() => useBroadcastMutations());

    await act(async () => {
      await result.current.remove("b1", onSuccess);
    });

    expect(onSuccess).toHaveBeenCalledOnce();
  });

  it("remove sets Error message on Error rejection", async () => {
    vi.mocked(broadcastsApi.deleteBroadcast).mockRejectedValue(
      new Error("not found"),
    );

    const { useBroadcastMutations } = await import("../../src/hooks/useBroadcasts");
    const { result } = renderHook(() => useBroadcastMutations());

    await act(async () => {
      await result.current.remove("b1");
    });

    expect(result.current.error).toBe("not found");
  });
});


