// Tests for useContactGroups hooks.
//
// Covers:
//   useContactGroupsList   — loading → ready, error, non-Error fallback, refresh
//   useContactGroup        — single group, error, non-Error fallback, refresh, id change
//   useContactGroupMutations — create/update/remove/addGroupMembers/removeGroupMembers
//                             + onSuccess, error, non-Error fallback, pending state

import { describe, it, expect, vi, beforeEach } from "vitest";
import { renderHook, act, waitFor } from "@testing-library/react";
import type {
  ContactGroup,
  ListContactGroupsResponse,
} from "../../src/api/types";

const GROUP: ContactGroup = {
  id: "g1",
  org_id: "o1",
  name: "VIPs",
  description: "",
  color: "blue",
  created_at: "2026-01-01T00:00:00Z",
};

const LIST_RESP: ListContactGroupsResponse = {
  groups: [GROUP],
};

// ─── Mock the api/contactGroups module ────────────────────────────────────────

vi.mock("../../src/api/contactGroups", () => ({
  listContactGroups: vi.fn(),
  getContactGroup: vi.fn(),
  createContactGroup: vi.fn(),
  updateContactGroup: vi.fn(),
  deleteContactGroup: vi.fn(),
  addMembers: vi.fn(),
  removeMembers: vi.fn(),
}));

import * as contactGroupsApi from "../../src/api/contactGroups";

// ─── useContactGroupsList ─────────────────────────────────────────────────────

describe("useContactGroupsList", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("starts in loading state and transitions to ready on success", async () => {
    vi.mocked(contactGroupsApi.listContactGroups).mockResolvedValue(LIST_RESP);

    const { useContactGroupsList } = await import(
      "../../src/hooks/useContactGroups"
    );
    const { result } = renderHook(() => useContactGroupsList());

    expect(result.current.state.tag).toBe("loading");

    await waitFor(() => {
      expect(result.current.state.tag).toBe("ready");
    });

    if (result.current.state.tag === "ready") {
      expect(result.current.state.response.groups).toHaveLength(1);
    }
  });

  it("transitions to error state when listContactGroups rejects with Error", async () => {
    vi.mocked(contactGroupsApi.listContactGroups).mockRejectedValue(
      new Error("network error"),
    );

    const { useContactGroupsList } = await import(
      "../../src/hooks/useContactGroups"
    );
    const { result } = renderHook(() => useContactGroupsList());

    await waitFor(() => {
      expect(result.current.state.tag).toBe("error");
    });

    if (result.current.state.tag === "error") {
      expect(result.current.state.message).toBe("network error");
    }
  });

  it("uses fallback message when non-Error is thrown", async () => {
    vi.mocked(contactGroupsApi.listContactGroups).mockRejectedValue("plain string");

    const { useContactGroupsList } = await import(
      "../../src/hooks/useContactGroups"
    );
    const { result } = renderHook(() => useContactGroupsList());

    await waitFor(() => {
      expect(result.current.state.tag).toBe("error");
    });

    if (result.current.state.tag === "error") {
      expect(result.current.state.message).toBe("Failed to load contact groups");
    }
  });

  it("refresh re-fetches the list", async () => {
    vi.mocked(contactGroupsApi.listContactGroups).mockResolvedValue(LIST_RESP);

    const { useContactGroupsList } = await import(
      "../../src/hooks/useContactGroups"
    );
    const { result } = renderHook(() => useContactGroupsList());

    await waitFor(() => expect(result.current.state.tag).toBe("ready"));

    act(() => {
      result.current.refresh();
    });

    await waitFor(() => {
      expect(contactGroupsApi.listContactGroups).toHaveBeenCalledTimes(2);
    });
  });
});

// ─── useContactGroup (single) ─────────────────────────────────────────────────

describe("useContactGroup", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("starts in loading state and transitions to ready on success", async () => {
    vi.mocked(contactGroupsApi.getContactGroup).mockResolvedValue(GROUP);

    const { useContactGroup } = await import("../../src/hooks/useContactGroups");
    const { result } = renderHook(() => useContactGroup("g1"));

    expect(result.current.state.tag).toBe("loading");

    await waitFor(() => {
      expect(result.current.state.tag).toBe("ready");
    });

    if (result.current.state.tag === "ready") {
      expect(result.current.state.group.id).toBe("g1");
    }
